public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    List<Integer> perm = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) {
        perm.add(nums[i]);
    }
    result.add(perm);
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[j] == nums[i]) {
                continue;
            }
            List<Integer> newPerm = new ArrayList<>(perm);
            newPerm.set(i, nums[j]);
            newPerm.set(j, nums[i]);
            result.add(newPerm);
        }
    }
    return result;
}

public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums.length == 0) {
            return result;
        }

        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            list.add(nums[i]);
        }

        // Store the permutation list of each length
        List<List<Integer>> permutationList = new ArrayList<>();
        permutationList.add(list);

        // Loop through each length to generate permutations
        for (int i = 1; i < nums.length; i++) {
            List<List<Integer>> tempList = new ArrayList<>();
            for (List<Integer> temp : permutationList) {
                for (int j = 0; j < temp.size(); j++) {
                    List<Integer> newList = new ArrayList<>(temp);
                    newList.add(j, nums[i]);
                    tempList.add(newList);
                }
            }
            permutationList.add(tempList);
        }

        // Add the permutation list of each length to the result
        for (List<Integer> temp : permutationList) {
            result.add(temp);
        }

        return result;
    }

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 1) {
        permutations.add(Arrays.asList(nums[0]));
    } else {
        for (int i = 0; i < nums.length; i++) {
            int n = nums[i];
            int[] remainingNums = new int[nums.length - 1];
            for (int j = 0, k = 0; j < nums.length; j++) {
                if (j != i) {
                    remainingNums[k++] = nums[j];
                }
            }
            List<List<Integer>> recursivePermutations = permute(remainingNums);
            for (List<Integer> permutation : recursivePermutations) {
                permutation.add(0, n);
                permutations.add(permutation);
            }
        }
    }
    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        List<Integer> list = new ArrayList<>();
        list.add(nums[0]);
        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int n = nums[i];
        int[] newNums = new int[nums.length - 1];
        for (int j = 0; j < nums.length; j++) {
            if (j != i) {
                newNums[j] = nums[j];
            }
        }
        List<List<Integer>> permutations = permute(newNums);
        for (List<Integer> permutation : permutations) {
            permutation.add(n);
            result.add(permutation);
        }
    }
    return result;
}

