public static int countOilDeposits(char[][] grid) {
    Map<Integer, Integer> deposits = new HashMap<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                int deposit = 0;
                for (int k = i; k < grid.length; k++) {
                    for (int l = j; l < grid[k].length; l++) {
                        if (grid[k][l] == '@') {
                            deposit++;
                        }
                    }
                }
                deposits.putIfAbsent(deposit, 0);
                deposits.put(deposit, deposits.get(deposit) + 1);
            }
        }
    }
    return deposits.values().stream().distinct().count();
}

