public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start.length != end.length || paths.length != n || start.length != paths[0].length || end.length != paths[0].length) {
        return "cannot be travelled";
    }
    boolean[][] visited = new boolean[n][n];
    for (int[] path : paths) {
        visited[path[0]][path[1]] = true;
    }
    for (int i = 0; i < n; i++) {
        if (!visited[start[0]][i]) {
            continue;
        }
        for (int j = 0; j < n; j++) {
            if (!visited[i][j] || visited[j][end[1]]) {
                continue;
            }
            for (int k = 0; k < n; k++) {
                if (visited[j][k]) {
                    visited[k][j] = true;
                }
            }
            if (visited[end[0]][j]) {
                return "can be travelled";
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int[] currentPosition = start;
    int[] endingPosition = end;
    boolean hasEndingPosition = false;

    while (!hasEndingPosition) {
        int x = currentPosition[0], y = currentPosition[1];
        int[] possibleMoves = {x + 1, y, x + 2, y, x, y + 1, x, y - 2, x - 1, y};
        for (int[] move : possibleMoves) {
            if (isValidMove(move, n, paths)) {
                currentPosition = move;
                hasEndingPosition = Arrays.equals(currentPosition, endingPosition);
            }
        }
    }

    return hasEndingPosition ? "can be travelled" : "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a 2D array to represent the maze
    boolean[][] maze = new boolean[n][n];
    // Populate the maze with false values
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            maze[i][j] = false;
        }
    }
    // Loop through the paths and mark them as true in the maze
    for (int[] path : paths) {
        maze[path[0]][path[1]] = true;
    }
    // Check if the start and end are connected in the maze
    boolean startConnected = maze[start[0]][start[1]];
    boolean endConnected = maze[end[0]][end[1]];
    if (startConnected && endConnected) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue for the breadth-first search
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start] = true;
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection to visit
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end) {
            return "can be travelled";
        }

        // Loop through all n-tersections that are connected to the current n-tersection
        for (int next : paths[current]) {
            // If the next n-tersection has not been visited, mark it as visited and add it to the queue
            if (!visited[next]) {
                visited[next] = true;
                queue.offer(next);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Initialize a boolean array to keep track of visited n-tersections
        boolean[] visited = new boolean[n];

        // Initialize a queue to perform BFS
        Queue<Integer> queue = new LinkedList<>();

        // Mark the starting n-tersection as visited and add it to the queue
        visited[start[0]] = true;
        queue.add(start[0]);

        // Loop until the queue is empty
        while (!queue.isEmpty()) {
            // Get the next n-tersection from the queue
            int current = queue.remove();

            // If the current n-tersection is the ending n-tersection, return "can be travelled"
            if (current == end[0]) {
                return "can be travelled";
            }

            // Loop through all the adjacent n-tersections
            for (int i = 0; i < paths.length; i++) {
                // If the adjacent n-tersection is not visited and is not blocked, mark it as visited and add it to the queue
                if (paths[current][i] == 1 && !visited[i]) {
                    visited[i] = true;
                    queue.add(i);
                }
            }
        }

        // If the queue is empty and the ending n-tersection was not visited, return "cannot be travelled"
        return "cannot be travelled";
    }

