public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int p = (int) (n * 0.05);
    int q = (int) (n * 0.95);
    int sum = 0;
    for (int i = p; i < q; i++) {
        sum += arr[i];
    }
    return sum / (n - 2 * p);
}

public double trimMean(int[] arr) {
    int len = arr.length;
    int trimLen = (int) Math.floor(0.05 * len);
    int[] sortedArr = Arrays.copyOf(arr, len);
    Arrays.sort(sortedArr);
    double sum = 0;
    for (int i = trimLen; i < len - trimLen; i++) {
        sum += sortedArr[i];
    }
    return sum / (len - 2 * trimLen);
}

