public boolean canArrange(int[] arr, int k) {
  if (arr.length % 2 != 0) {
    return false;
  }

  int sum = 0;
  for (int i = 0; i < arr.length; i++) {
    sum += arr[i];
  }

  if (sum % k != 0) {
    return false;
  }

  int target = sum / k;
  int count = 0;
  int currentSum = 0;
  for (int i = 0; i < arr.length; i++) {
    currentSum += arr[i];
    if (currentSum == target) {
      count++;
      currentSum = 0;
    }
  }

  return count == arr.length / 2;
}

