public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph represented as an adjacency list
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Initialize a boolean array to keep track of which nodes have apples
    boolean[] hasApple = new boolean[n];
    for (int i = 0; i < hasApple.length; i++) {
        hasApple[i] = false;
    }

    for (int i = 0; i < edges.length; i++) {
        if (hasApple[edges[i][0]] || hasApple[edges[i][1]]) {
            hasApple[edges[i][0]] = true;
            hasApple[edges[i][1]] = true;
        }
    }

    // Initialize a priority queue to store the nodes to visit, with the node 0 as the first element
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    queue.add(0);

    // Initialize a variable to keep track of the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    while (!queue.isEmpty()) {
        int node = queue.poll();

        // If the current node has an apple, add the time it takes to collect it to the minimum time
        if (hasApple[node]) {
            minTime += 2;
        }

        // Add the time it takes to visit the current node to the minimum time
        minTime += 1;

        // For each neighbor of the current node that has not been visited, update the minimum time required to visit it
        for (int neighbor : graph.get(node)) {
            if (!queue.contains(neighbor)) {
                queue.add(neighbor);
            }
        }
    }

    return minTime;
}

