    Collections.sort(list);
    StringBuilder builder = new StringBuilder();
    boolean ascending = true;
    while (!list.isEmpty()) {
        if (ascending) {
            builder.append(list.remove(0));
        } else {
            builder.append(list.remove(list.size() - 1));
        }
        ascending = !ascending;
    }
    return builder.toString();
}

