public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    int n = nums.length;
    for (int i = 0; i < n; i++) {
        sum += nums[i];
    }
    double average = (double) sum / n;
    boolean result = false;
    for (int i = 0; i < n; i++) {
        int sum1 = 0;
        int count1 = 0;
        int sum2 = 0;
        int count2 = 0;
        for (int j = i; j < n; j++) {
            if (nums[j] % 2 == 0) {
                sum1 += nums[j];
                count1++;
            } else {
                sum2 += nums[j];
                count2++;
            }
        }
        if (count1 > 0 && count2 > 0 && Math.abs(sum1 / count1 - average) < 1e-9 && Math.abs(sum2 / count2 - average) < 1e-9) {
            result = true;
            break;
        }
    }
    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum and size of the array
    int sum = 0;
    int size = 0;
    for (int num : nums) {
        sum += num;
        size++;
    }
    // Check if the average is an integer
    if (sum % size != 0) {
        return false;
    }
    int target = sum / size;
    // Check if any two elements sum up to the target
    for (int i = 0; i < nums.length - 1; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return true;
            }
        }
    }
    return false;
}

