    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    for (int i = 0; i < nums.length; i++) {
        int firstSum = 0;
        for (int j = 0; j < i; j++) {
            firstSum += nums[j];
        }
        int secondSum = totalSum - firstSum;
        if (firstSum * nums.length == secondSum * (nums.length - i)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost){
    int start = 0;
    int end = 0;
    int minCost = cost[0];
    for(int i = 2; i < cost.length; i++){
        if(cost[i] < minCost){
            start = end;
            end = i;
            minCost = cost[i];
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
  int minCost = 0;
  for (int i = 0; i < cost.length; i++) {
    if (i == 0) {
      minCost = Math.min(minCost, cost[i]);
    } else if (i == 1) {
      minCost = Math.min(minCost, cost[i] + cost[i - 1]);
    } else {
      minCost = Math.min(minCost, cost[i] + cost[i - 1] + cost[i - 2]);
    }
  }
  return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int cost0 = 0, cost1 = 0;
    for (int i = 0; i < cost.length; i++) {
        int cost0new = Math.min(cost0, cost1) + cost[i];
        cost1 = cost0;
        cost0 = cost0new;
    }
    return Math.min(cost0, cost1);
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < cost.length; i++) {
        int curCost = cost[i];
        if (i > 0) {
            curCost += cost[i - 1];
        }
        minCost = Math.min(minCost, curCost);
    }
    return minCost;
}

