public int minInsertions(String s) {
    int openingBrackets = 0;
    int closingBrackets = 0;
    int minInsertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            openingBrackets++;
        } else if (s.charAt(i) == ')') {
            closingBrackets++;
        }
    }

    minInsertions = Math.abs(openingBrackets - closingBrackets);

    return minInsertions;
}

