    for (int i = 0; i < sb.length(); i++) {
        char c = sb.charAt(i);
        char opposite = Character.isUpperCase(c) ? Character.toLowerCase(c) : Character.toUpperCase(c);
        for (int j = i + 1; j < sb.length(); j++) {
            if (sb.charAt(j) == opposite) {
