  for (char c : s.toCharArray()) {
    if (stack.isEmpty()) {
      stack.push(c);
    } else if (Math.abs(stack.getFirst() - c) == 32) {
      stack.pop();
    } else {
      stack.push(c);
    }
  }
  StringBuilder sb = new StringBuilder();
  while (!stack.isEmpty()) {
    sb.append(stack.pollFirst());
  }
  return sb.toString();
}

