def square_permutations(A):
    # Check if the input array is valid
    if not A:
        return 0

    # Initialize a set to store the results
    results = set()

    # Get the length of the input array
    n = len(A)

    # Loop through each possible permutation of the input array
    for i in range(n):
        permutation = A[i:] + A[:i]
        is_square_permutation = True
        for j in range(n - 1):
            if permutation[j] + permutation[j + 1] not in results:
                is_square_permutation = False
                break
        if is_square_permutation:
            results.add(permutation)

    return len(results)

