        if (s.charAt(i) == s.charAt(start)) {
            // If it is the same, increment the length of the current substring
            longest++;
        } else {
            // If it is not the same, update the start index of the current substring
            start = i;
            // Reset the length of the current substring
            longest = 1;
        }
    }
    // Return the length of the longest non-empty substring containing only one character
    return longest;
}

