public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
        List<Integer> perfectSquares = new ArrayList<>();
        int minSum = Integer.MAX_VALUE;
        int perfectSquareSum = 0;
        int index = 0;
        while (perfectSquareSum <= n) {
            int currentSquare = index * index;
            perfectSquares.add(currentSquare);
            perfectSquareSum += currentSquare;
            if (perfectSquareSum == n) {
                minSum = Math.min(minSum, perfectSquares.size());
                break;
            } else if (perfectSquareSum > n) {
                perfectSquares.remove(perfectSquares.size() - 1);
                perfectSquareSum -= perfectSquares.get(perfectSquares.size() - 1);
                minSum = Math.min(minSum, perfectSquares.size() + 1);
                index++;
            }
        }
        return minSum;
    }

